// Body parser: JSON or application/x-www-form-urlencoded
async function _parseBody(req) {
  const ct = req.headers.get('content-type') ?? ''
  if (ct.includes('application/json')) return req.json()
  if (ct.includes('application/x-www-form-urlencoded')) {
    const text = await req.text()
    return Object.fromEntries(new URLSearchParams(text))
  }
  if (ct.includes('multipart/form-data')) {
    const fd = await req.formData()
    return Object.fromEntries(fd.entries())
  }
  return {}
}

// ── Auth helpers ──────────────────────────────────────────────────────────────

const _AUTH_SECRET = process.env.SESSION_SECRET ?? 'change-me-in-production'
const _SESSION_COOKIE = 'arc_session'
const _SESSION_MAX_AGE = 604800

// HMAC-SHA256 sign/verify (Web Crypto — built into Bun + Node 18+)
async function _hmacSign(data, secret) {
  const enc = new TextEncoder()
  const key = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign'])
  const sig = await crypto.subtle.sign('HMAC', key, enc.encode(data))
  return btoa(String.fromCharCode(...new Uint8Array(sig))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '')
}

async function _hmacVerify(data, sig, secret) {
  const expected = await _hmacSign(data, secret)
  return expected === sig
}

// Session: encode/decode signed cookie value
async function _sessionEncode(payload) {
  const json = JSON.stringify(payload)
  const b64 = btoa(encodeURIComponent(json))
  const sig = await _hmacSign(b64, _AUTH_SECRET)
  return `${b64}.${sig}`
}

async function _sessionDecode(cookieValue) {
  if (!cookieValue) return null
  const dot = cookieValue.lastIndexOf('.')
  if (dot === -1) return null
  const b64 = cookieValue.slice(0, dot)
  const sig = cookieValue.slice(dot + 1)
  if (!await _hmacVerify(b64, sig, _AUTH_SECRET)) return null
  try {
    return JSON.parse(decodeURIComponent(atob(b64)))
  } catch { return null }
}

// Parse cookies from a request
function _parseCookies(req) {
  const header = req.headers.get('cookie') ?? ''
  const cookies = {}
  for (const part of header.split(';')) {
    const [k, ...vs] = part.trim().split('=')
    if (k) cookies[k.trim()] = decodeURIComponent(vs.join('='))
  }
  return cookies
}

// auth object injected into every route handler
const auth = {
  // Read session from request → returns session payload or null
  session: async (req) => {
    const cookies = _parseCookies(req)
    return _sessionDecode(cookies[_SESSION_COOKIE])
  },

  // Set session cookie on a Response (mutates headers)
  set: async (res, payload) => {
    const value = await _sessionEncode(payload)
    const cookie = `${_SESSION_COOKIE}=${value}; HttpOnly; SameSite=Lax; Max-Age=${_SESSION_MAX_AGE}; Path=/`
    return new Response(res.body, {
      status: res.status,
      headers: { ...Object.fromEntries(res.headers), 'Set-Cookie': cookie }
    })
  },

  // Clear session cookie on a Response
  clear: (res) => {
    const cookie = `${_SESSION_COOKIE}=; HttpOnly; SameSite=Lax; Max-Age=0; Path=/`
    return new Response(res.body, {
      status: res.status,
      headers: { ...Object.fromEntries(res.headers), 'Set-Cookie': cookie }
    })
  },

  // Require auth: return 401 if no session, else return session payload
  require: async (req) => {
    const sess = await auth.session(req)
    if (!sess) throw Object.assign(new Error('Unauthorized'), { _authError: true })
    return sess
  },
}

// JWT (HS256 via Web Crypto)
const jwt = {
  sign: async (payload, secret = _AUTH_SECRET, expiresIn = 3600) => {
    const header = { alg: 'HS256', typ: 'JWT' }
    const now = Math.floor(Date.now() / 1000)
    const claims = { ...payload, iat: now, exp: now + expiresIn }
    const enc = new TextEncoder()
    const b64url = (obj) => btoa(JSON.stringify(obj)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '')
    const unsigned = `${b64url(header)}.${b64url(claims)}`
    const sig = await _hmacSign(unsigned, secret)
    return `${unsigned}.${sig}`
  },

  verify: async (token, secret = _AUTH_SECRET) => {
    const parts = token.split('.')
    if (parts.length !== 3) return null
    const [headerB64, payloadB64, sig] = parts
    if (!await _hmacVerify(`${headerB64}.${payloadB64}`, sig, secret)) return null
    try {
      const payload = JSON.parse(atob(payloadB64.replace(/-/g, '+').replace(/_/g, '/')))
      if (payload.exp && payload.exp < Math.floor(Date.now() / 1000)) return null
      return payload
    } catch { return null }
  },
}

// OAuth helpers (GitHub)
const oauth = {
  github: {
    url: (scopes = ['user:email']) => {
      const clientId = process.env.GITHUB_CLIENT_ID ?? ''
      const params = new URLSearchParams({ client_id: clientId, scope: scopes.join(' ') })
      return `https://github.com/login/oauth/authorize?${params}`
    },
    callback: async (req) => {
      const url = new URL(req.url)
      const code = url.searchParams.get('code')
      if (!code) return { ok: false, error: 'no_code' }
      const tokenRes = await fetch('https://github.com/login/oauth/access_token', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
        body: JSON.stringify({
          client_id: process.env.GITHUB_CLIENT_ID,
          client_secret: process.env.GITHUB_CLIENT_SECRET,
          code,
        }),
      })
      const { access_token, error } = await tokenRes.json()
      if (error || !access_token) return { ok: false, error: error ?? 'token_exchange_failed' }
      const userRes = await fetch('https://api.github.com/user', {
        headers: { Authorization: `Bearer ${access_token}`, 'User-Agent': 'arc-server' }
      })
      const user = await userRes.json()
      return { ok: true, user, accessToken: access_token }
    },
  },

  google: {
    url: (scopes = ['email', 'profile']) => {
      const clientId = process.env.GOOGLE_CLIENT_ID ?? ''
      const redirectUri = process.env.GOOGLE_REDIRECT_URI ?? ''
      const params = new URLSearchParams({
        client_id: clientId,
        redirect_uri: redirectUri,
        response_type: 'code',
        scope: scopes.join(' '),
      })
      return `https://accounts.google.com/o/oauth2/v2/auth?${params}`
    },
    callback: async (req) => {
      const url = new URL(req.url)
      const code = url.searchParams.get('code')
      if (!code) return { ok: false, error: 'no_code' }
      const redirectUri = process.env.GOOGLE_REDIRECT_URI ?? ''
      const tokenRes = await fetch('https://oauth2.googleapis.com/token', {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
          client_id: process.env.GOOGLE_CLIENT_ID,
          client_secret: process.env.GOOGLE_CLIENT_SECRET,
          redirect_uri: redirectUri,
          grant_type: 'authorization_code',
          code,
        }),
      })
      const { access_token, id_token, error } = await tokenRes.json()
      if (error || !access_token) return { ok: false, error: error ?? 'token_exchange_failed' }
      const userRes = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', {
        headers: { Authorization: `Bearer ${access_token}` }
      })
      const user = await userRes.json()
      return { ok: true, user, accessToken: access_token, idToken: id_token }
    },
  },
}

// ── Queue ─────────────────────────────────────────────────────────────────────

const _queue = {
  _items: [],
  _running: false,
  enqueue(fn, args, retries = 0) {
    this._items.push({ fn, args, retries })
    if (!this._running) this._process()
  },
  async _process() {
    this._running = true
    while (this._items.length > 0) {
      const { fn, args, retries } = this._items.shift()
      try {
        await fn(...args)
      } catch (_e) {
        console.error('[arc:queue] job error:', _e?.message ?? _e)
        if (retries < 3) {
          const delay = Math.pow(2, retries) * 200
          setTimeout(() => this.enqueue(fn, args, retries + 1), delay)
        } else {
          console.error('[arc:queue] job permanently failed after 3 retries')
        }
      }
    }
    this._running = false
  }
}

const Queue = {
  enqueue: (fn, ...args) => _queue.enqueue(fn, args),
  size: () => _queue._items.length,
  drain: () => new Promise(resolve => {
    const check = () => _queue._items.length === 0 && !_queue._running ? resolve() : setTimeout(check, 10)
    check()
  }),
}

// ── Email ─────────────────────────────────────────────────────────────────────

const email = {
  send: async ({ to, subject, text, html, from, replyTo }) => {
    const resendKey = process.env.RESEND_API_KEY
    if (resendKey) {
      const res = await fetch('https://api.resend.com/emails', {
        method: 'POST',
        headers: { Authorization: `Bearer ${resendKey}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({
          from: from ?? process.env.EMAIL_FROM ?? 'noreply@example.com',
          to: Array.isArray(to) ? to : [to],
          subject,
          text,
          html,
          reply_to: replyTo,
        }),
      })
      if (!res.ok) {
        const err = await res.text().catch(() => res.status)
        throw new Error(`[arc:email] Resend error: ${err}`)
      }
      return res.json()
    }
    // SMTP fallback via nodemailer
    try {
      const nodemailer = require('nodemailer')
      const transport = nodemailer.createTransport({
        host: process.env.SMTP_HOST ?? 'localhost',
        port: +(process.env.SMTP_PORT ?? 587),
        secure: process.env.SMTP_SECURE === 'true',
        auth: process.env.SMTP_USER
          ? { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS }
          : undefined,
      })
      return transport.sendMail({
        from: from ?? process.env.EMAIL_FROM ?? 'noreply@example.com',
        to, subject, text, html,
        replyTo,
      })
    } catch {
      console.warn('[arc:email] No provider configured — set RESEND_API_KEY or SMTP_HOST.')
    }
  },
}

