function _dispatch(req, url) {
  const segments = url.pathname.slice(1).split('/').filter(Boolean)
  const method = req.method
  const params = {}
    const seg0 = segments[0]
  switch (seg0) {
    case 'auth': {
      const seg1 = segments[1]
      switch (seg1) {
        case 'github': {
          if (segments.length === 2) {
            switch (method) {
              case 'GET': return _route_get_auth_github(req, params)
              default: return new Response('Method Not Allowed', { status: 405 })
            }
          }
          const seg2 = segments[2]
          switch (seg2) {
            case 'callback': {
              switch (method) {
                case 'GET': return _route_get_auth_github_callback(req, params)
                default: return new Response('Method Not Allowed', { status: 405 })
              }
            }
            default: return new Response('Not Found', { status: 404 })
          }
        }
        case 'logout': {
          switch (method) {
            case 'POST': return _route_post_auth_logout(req, params)
            default: return new Response('Method Not Allowed', { status: 405 })
          }
        }
        case 'me': {
          switch (method) {
            case 'GET': return _route_get_auth_me(req, params)
            default: return new Response('Method Not Allowed', { status: 405 })
          }
        }
        case 'profile': {
          switch (method) {
            case 'GET': return _route_get_auth_profile(req, params)
            default: return new Response('Method Not Allowed', { status: 405 })
          }
        }
        default: return new Response('Not Found', { status: 404 })
      }
    }
    case 'posts': {
      if (segments.length === 1) {
        switch (method) {
          case 'GET': return _route_get_posts(req, params)
          case 'POST': return _route_post_posts(req, params)
          default: return new Response('Method Not Allowed', { status: 405 })
        }
      }
      params['id'] = segments[1]
      switch (method) {
        case 'GET': return _route_get_posts__id(req, params)
        case 'DELETE': return _route_delete_posts__id(req, params)
        default: return new Response('Method Not Allowed', { status: 405 })
      }
    }
    case 'health': {
      switch (method) {
        case 'GET': return _route_get_health(req, params)
        default: return new Response('Method Not Allowed', { status: 405 })
      }
    }
    default: return new Response('Not Found', { status: 404 })
  }
  return new Response('Not Found', { status: 404 })
}

// Start Bun server
const _server = Bun.serve({
  port: +(process.env.PORT ?? 3000),
  async fetch(req) {
    const url = new URL(req.url)
    return _dispatch(req, url)
  }
})
console.log(`arc: server running on http://localhost:${_server.port}`)